from z3 import *

# Enumerations
NAME = {"Eric": 0, "Arnold": 1}
HOBBY = {"gardening": 0, "photography": 1}
MUSIC = {"rock": 0, "pop": 1}
MOTHER = {"Holly": 0, "Aniya": 1}

# reverse maps for printing
rNAME = {v: k for k, v in NAME.items()}
rHOBBY = {v: k for k, v in HOBBY.items()}
rMUSIC = {v: k for k, v in MUSIC.items()}
rMOTHER = {v: k for k, v in MOTHER.items()}

# Two houses, indexed 0 (House 1) and 1 (House 2)
name   = [Int(f"name_{i}")   for i in range(2)]
hobby  = [Int(f"hobby_{i}")  for i in range(2)]
music  = [Int(f"music_{i}")  for i in range(2)]
mother = [Int(f"mother_{i}") for i in range(2)]

s = Solver()

# Domain constraints
for arr, domain in [(name, NAME), (hobby, HOBBY),
                    (music, MUSIC), (mother, MOTHER)]:
    for v in arr:
        s.add(Or([v == val for val in domain.values()]))

# All‑different within each category (permutation of the two values)
s.add(Distinct(name))
s.add(Distinct(hobby))
s.add(Distinct(music))
s.add(Distinct(mother))

# Helper: position of a particular attribute value
def position_of(arr, value):
    # sum of indices where arr[i] == value (exactly one such i)
    return Sum([If(arr[i] == value, i, 0) for i in range(2)])

# Clue 1: photography hobby is to the right of Eric
p_pos = position_of(hobby, HOBBY["photography"])
e_pos = position_of(name,  NAME["Eric"])
s.add(p_pos > e_pos)

# Clue 2: mother Holly ↔ photography hobby
for i in range(2):
    s.add(Implies(mother[i] == MOTHER["Holly"], hobby[i] == HOBBY["photography"]))
    s.add(Implies(hobby[i] == HOBBY["photography"], mother[i] == MOTHER["Holly"]))

# Clue 3: Arnold loves rock music
for i in range(2):
    s.add(Implies(name[i] == NAME["Arnold"], music[i] == MUSIC["rock"]))

# Solve and print
if s.check() == sat:
    m = s.model()
    for i in range(2):
        house_num = i + 1
        n = rNAME[m[name[i]].as_long()]
        h = rHOBBY[m[hobby[i]].as_long()]
        mu = rMUSIC[m[music[i]].as_long()]
        mo = rMOTHER[m[mother[i]].as_long()]
        print(f"House {house_num}: {n}, {h}, {mu}, {mo}")
else:
    print("No solution found.")

from z3 import *

# Constants for mapping attributes to integers
Names = {"Arnold": 0, "Peter": 1, "Eric": 2}
Flowers = {"daffodils": 0, "lilies": 1, "carnations": 2}
Nations = {"brit": 0, "dane": 1, "swede": 2}
Mothers = {"Aniya": 0, "Holly": 1, "Janelle": 2}
Sports = {"basketball": 0, "tennis": 1, "soccer": 2}

# Reverse maps for printing
rev_Name = {v: k for k, v in Names.items()}
rev_Flower = {v: k for k, v in Flowers.items()}
rev_Nation = {v: k for k, v in Nations.items()}
rev_Mother = {v: k for k, v in Mothers.items()}
rev_Sport = {v: k for k, v in Sports.items()}

# There are three houses indexed 0,1,2 (house 1 = index 0)
HouseCount = 3
idx = range(HouseCount)

# Create variables: each house gets a value for each category
name = [Int(f"name_{i}") for i in idx]
flower = [Int(f"flower_{i}") for i in idx]
nation = [Int(f"nation_{i}") for i in idx]
mother = [Int(f"mother_{i}") for i in idx]
sport = [Int(f"sport_{i}") for i in idx]

s = Solver()

# Domain constraints (0..2) and distinctness within each category
for varlist in (name, flower, nation, mother, sport):
    for v in varlist:
        s.add(And(v >= 0, v <= 2))
    s.add(Distinct(*varlist))

# Clue 1: Swedish person is not in the third house (index 2)
s.add(nation[2] != Nations["swede"])

# Clue 2: basketball directly left of tennis
s.add(Or(
    And(sport[0] == Sports["basketball"], sport[1] == Sports["tennis"]),
    And(sport[1] == Sports["basketball"], sport[2] == Sports["tennis"])
))

# Clue 3: Arnold loves lilies
for i in idx:
    s.add(Implies(name[i] == Names["Arnold"], flower[i] == Flowers["lilies"]))

# Clue 4: Mother Janelle -> Dane
for i in idx:
    s.add(Implies(mother[i] == Mothers["Janelle"], nation[i] == Nations["dane"]))

# Clue 5: Mother Holly -> carnations
for i in idx:
    s.add(Implies(mother[i] == Mothers["Holly"], flower[i] == Flowers["carnations"]))

# Clue 6: Lilies (flower) is somewhere to the right of Peter (name)
for i in idx:
    for j in idx:
        s.add(Implies(And(flower[i] == Flowers["lilies"], name[j] == Names["Peter"]), i > j))

# Clue 7: Dane directly left of carnations
s.add(Or(
    And(nation[0] == Nations["dane"], flower[1] == Flowers["carnations"]),
    And(nation[1] == Nations["dane"], flower[2] == Flowers["carnations"])
))

# Clue 8: Eric is not in the first house (index 0)
s.add(name[0] != Names["Eric"])

# Clue 9: Mother Janelle directly left of basketball lover
s.add(Or(
    And(mother[0] == Mothers["Janelle"], sport[1] == Sports["basketball"]),
    And(mother[1] == Mothers["Janelle"], sport[2] == Sports["basketball"])
))

# Solve
if s.check() == sat:
    m = s.model()
    for i in idx:
        house_no = i + 1
        n = rev_Name[m[name[i]].as_long()]
        f = rev_Flower[m[flower[i]].as_long()]
        nat = rev_Nation[m[nation[i]].as_long()]
        mor = rev_Mother[m[mother[i]].as_long()]
        sp = rev_Sport[m[sport[i]].as_long()]
        print(f"House {house_no}: {n}, {f}, {nat}, {mor}, {sp}")
else:
    print("No solution found.")
